def longest_words(words):
    m = max(len(w) for w in words)
    return sorted([w for w in words if len(w) == m])

def shortest_words(words):
    m = min(len(w) for w in words)
    return sorted([w for w in words if len(w) == m])

def value_frequency(d):
    result = {}
    for v in d.values():
        result[v] = result.get(v, 0) + 1
    return result

def common_prefix_counts(words, prefix_len):
    result = {}
    for w in words:
        if len(w) >= prefix_len:
            p = w[:prefix_len]
            result[p] = result.get(p, 0) + 1
    return result

def score_bucket_counts(scores):
    result = {}
    for s in scores:
        if s >= 100:
            label = "100+"
        else:
            low = (s // 10) * 10
            label = f"{low}-{low + 9}"
        result[label] = result.get(label, 0) + 1
    return result

def key_length_frequency(d):
