    for k in d:
        L = len(k)
        result[L] = result.get(L, 0) + 1
    return result

def merge_three_sum(d1, d2, d3):
    keys = set(d1) | set(d2) | set(d3)
    return {k: d1.get(k, 0) + d2.get(k, 0) + d3.get(k, 0) for k in keys}

def group_by_key_range(d, low, high):
    in_range = sorted(k for k, v in d.items() if low <= v <= high)
    out_range = sorted(k for k, v in d.items() if not (low <= v <= high))
    return {"in_range": in_range, "out_range": out_range}

def merge_avg_two(d1, d2):
    keys = set(d1) | set(d2)
    result = {}
    for k in keys:
        vals = []
        if k in d1:
            vals.append(d1[k])
        if k in d2:
            vals.append(d2[k])
        result[k] = sum(vals) / len(vals)
    return result

def unflatten_dict(flat, sep):
    result = {}
    for key, value in flat.items():
        parts = key.split(sep)
        d = result
        for p in parts[:-1]:
            d = d.setdefault(p, {})
        d[parts[-1]] = value
    return result

