def unflatten_tuple_keys(d):
    result = {}
    for keytuple, value in d.items():
        cur = result
        for p in keytuple[:-1]:
            cur = cur.setdefault(p, {})
        cur[keytuple[-1]] = value
    return result

def get_nested(d, path, sep, default):
    parts = path.split(sep)
    cur = d
    for p in parts:
        if not isinstance(cur, dict) or p not in cur:
            return default
        cur = cur[p]
    return cur

import copy


def set_nested(d, path, value, sep):
    result = copy.deepcopy(d)
    parts = path.split(sep)
    cur = result
    for p in parts[:-1]:
        if p not in cur or not isinstance(cur[p], dict):
            cur[p] = {}
        cur = cur[p]
    cur[parts[-1]] = value
    return result

def recursive_merge_sum_leaves(a, b):
    result = {}
    keys = set(a) | set(b)
    for k in keys:
        if k in a and k in b:
            av, bv = a[k], b[k]
            if isinstance(av, dict) and isinstance(bv, dict):
                result[k] = recursive_merge_sum_leaves(av, bv)
            elif (
                isinstance(av, (int, float))
                and not isinstance(av, bool)
                and isinstance(bv, (int, float))
                and not isinstance(bv, bool)
            ):
                result[k] = av + bv
            else:
                result[k] = bv
        elif k in b:
            result[k] = b[k]
        else:
            result[k] = a[k]
    return result

def flatten_list_of_dicts(records):
    result = {}
    for i, rec in enumerate(records):
        for k, v in rec.items():
            result[f"{i}.{k}"] = v
    return result

def dict_diff_labels(old, new):
    result = {}
    for k in old:
        if k in new:
            if new[k] > old[k]:
                result[k] = "increased"
            elif new[k] < old[k]:
                result[k] = "decreased"
            else:
                result[k] = "same"
    return result

def common_keys_all(dicts_list):
    if not dicts_list:
        return []
    common = set(dicts_list[0])
    for d in dicts_list[1:]:
        common &= set(d)
    return sorted(common)
